    57|  if (state.healthMarkers && Object.keys(state.healthMarkers).length > 0) {
    58|    lines.push(`  Deploy Markers (proof of what's live):`);
    59|    for (const [key, value] of Object.entries(state.healthMarkers)) {
    60|      lines.push(`    ${key}: ${value}`);
    61|    }
    62|  }
    63|
    64|  lines.push(`  Context fetched at: ${timestamp}`);
    65|  lines.push('[/IVX LIVE PRODUCTION CONTEXT]');
    66|
    67|  return lines.join('\n');
