     1|/**
     2| * IVX Production State — In-process shared state for live context injection.
     3| *
     4| * Owner mandate 2026-07-30: The live context injector was making HTTP calls
     5| * to localhost which fail on Render. This module holds the production state
     6| * in-process so the context injector can read it without HTTP fetches.
     7| *
     8| * hono.ts calls setProductionState() on boot with the live values.
     9| * The context injector calls getProductionState() to read them.
    10| */
    11|
    12|export type ProductionState = {
    13|  commit: string;
    14|  bootTime: string;
    15|  environment: string;
    16|  serviceName: string;
    17|  status: string;
    18|  schedulerRunning: boolean;
    19|  processStartedAt: string;
    20|  healthMarkers: Record<string, string>;
    21|};
    22|
    23|let currentState: ProductionState | null = null;
    24|
    25|/**
    26| * Set the production state. Called by hono.ts on boot and health check.
    27| */
    28|export function setProductionState(state: Partial<ProductionState>): void {
    29|  currentState = {
    30|    commit: state.commit ?? currentState?.commit ?? 'unknown',
    31|    bootTime: state.bootTime ?? currentState?.bootTime ?? new Date().toISOString(),
    32|    environment: state.environment ?? currentState?.environment ?? 'production',
    33|    serviceName: state.serviceName ?? currentState?.serviceName ?? 'ivx-holdings-platform',
    34|    status: state.status ?? currentState?.status ?? 'healthy',
    35|    schedulerRunning: state.schedulerRunning ?? currentState?.schedulerRunning ?? true,
    36|    processStartedAt: state.processStartedAt ?? currentState?.processStartedAt ?? new Date().toISOString(),
    37|    healthMarkers: state.healthMarkers ?? currentState?.healthMarkers ?? {},
    38|  };
    39|}
    40|
    41|/**
    42| * Get the current production state. Returns null if not yet set.
    43| */
    44|export function getProductionState(): ProductionState | null {
    45|  return currentState;
    46|}
    47|
    48|/**
    49| * Check if production state has been initialized.
    50| */
    51|export function isProductionStateSet(): boolean {
    52|  return currentState !== null;
    53|}

