import urllib.request, json, base64, gzip, time, sys

TOKEN = open('/tmp/owner_token.txt').read().strip()
API = 'https://api.ivxholding.com'

def encode_file(path):
    with open(path, 'rb') as f:
        raw = f.read()
    compressed = gzip.compress(raw)
    return base64.b64encode(compressed).decode('ascii')

files = [
    {
        'path': 'backend/services/ivx-senior-engineer-persona.ts',
        'content': encode_file('/home/user/rork-app/backend/services/ivx-senior-engineer-persona.ts'),
        'contentEncoding': 'gzip-base64',
    },
    {
        'path': 'backend/api/ivx-owner-ai.ts',
        'content': encode_file('/home/user/rork-app/backend/api/ivx-owner-ai.ts'),
        'contentEncoding': 'gzip-base64',
    },
    {
        'path': 'backend/hono.ts',
        'content': encode_file('/home/user/rork-app/backend/hono.ts'),
        'contentEncoding': 'gzip-base64',
    },
]

payload = {
    'action': 'github_commit_multi_file',
    'confirm': True,
    'confirmText': 'CONFIRM_IVX_GITHUB_WRITE',
    'input': {
        'files': files,
        'commitMessage': 'fix(ia): V3 context attention fix — move live context to top of prompt, add mandatory reading rules, inject compact context prefix into user message. Fixes 3 Phase 8 failures (priority question, production SHA, production health).',
    },
}

data = json.dumps(payload).encode('utf-8')
req = urllib.request.Request(
    f'{API}/api/ivx/developer-deploy/action',
    data=data,
    headers={
        'Content-Type': 'application/json',
        'Authorization': f'Bearer {TOKEN}',
    },
    method='POST'
)

try:
    resp = urllib.request.urlopen(req, timeout=60)
    result = json.loads(resp.read())
    print(json.dumps(result, indent=2)[:3000])
    if result.get('ok') or result.get('sha'):
        sha = result.get('sha') or result.get('commitSha') or result.get('input', {}).get('sha', 'unknown')
